/**
 * Tooltip Component
 *
 * A fully accessible tooltip component for providing contextual information.
 *
 * @example
 * ```tsx
 * import { Tooltip, TooltipProvider, TooltipGroup } from '@dsai-io/react';
 *
 * <TooltipProvider>
 *   <TooltipGroup>
 *     <Tooltip content="Bold"><button>B</button></Tooltip>
 *     <Tooltip content="Italic"><button>I</button></Tooltip>
 *   </TooltipGroup>
 * </TooltipProvider>
 * ```
 */
export { Tooltip } from './Tooltip';
export { TooltipProvider } from './TooltipProvider';
export { TooltipGroup } from './TooltipGroup';
export {
  createInitialTooltipFSMState,
  getTooltipVisualState,
  tooltipFSMReducer,
} from './Tooltip.fsm';
export type {
  TooltipContextValue,
  TooltipFSMEvent,
  TooltipFSMState,
  TooltipGroupProps,
  TooltipPlacement,
  TooltipProps,
  TooltipProviderProps,
  TooltipTrigger,
  TooltipVisualState,
} from './Tooltip.types';

import type { TooltipFSMEvent, TooltipFSMState, TooltipVisualState } from './Tooltip.types';

/**
 * Create initial FSM state for the Tooltip
 *
 * @param initialOpen - Initial open state
 * @returns Initial FSM state
 */
export function createInitialTooltipFSMState(initialOpen: boolean): TooltipFSMState {
  if (initialOpen) {
    return {
      visibility: 'open',
      shouldRender: true,
    };
  }
  return {
    visibility: 'closed',
    shouldRender: false,
  };
}

/**
 * Tooltip FSM Reducer
 *
 * State machine for managing tooltip visibility with animation support.
 *
 * States:
 * - closed: Tooltip is hidden and not rendered
 * - opening: Tooltip is being shown (animation in progress)
 * - open: Tooltip is fully visible
 * - closing: Tooltip is being hidden (animation in progress)
 *
 * Transitions:
 * - closed + OPEN -> opening (start show animation)
 * - opening + ANIMATION_END -> open (show animation complete)
 * - open + CLOSE -> closing (start hide animation)
 * - closing + ANIMATION_END -> closed (hide animation complete)
 *
 * @param state - Current FSM state
 * @param event - Event to process
 * @returns New FSM state
 */
export function tooltipFSMReducer(state: TooltipFSMState, event: TooltipFSMEvent): TooltipFSMState {
  switch (state.visibility) {
    case 'closed':
      if (event.type === 'OPEN') {
        return {
          visibility: 'opening',
          shouldRender: true,
        };
      }
      return state;

    case 'opening':
      if (event.type === 'ANIMATION_END') {
        return {
          visibility: 'open',
          shouldRender: true,
        };
      }
      if (event.type === 'CLOSE') {
        return {
          visibility: 'closing',
          shouldRender: true,
        };
      }
      return state;

    case 'open':
      if (event.type === 'CLOSE') {
        return {
          visibility: 'closing',
          shouldRender: true,
        };
      }
      return state;

    case 'closing':
      if (event.type === 'ANIMATION_END') {
        return {
          visibility: 'closed',
          shouldRender: false,
        };
      }
      if (event.type === 'OPEN') {
        return {
          visibility: 'opening',
          shouldRender: true,
        };
      }
      return state;

    default:
      return state;
  }
}

/**
 * Get visual state string for data-visual-state attribute
 *
 * Maps FSM visibility to user-friendly visual state names:
 * - closed -> 'hidden'
 * - opening -> 'showing'
 * - open -> 'visible'
 * - closing -> 'hiding'
 *
 * @param state - Current FSM state
 * @returns Visual state string for CSS/testing
 */
export function getTooltipVisualState(state: TooltipFSMState): TooltipVisualState {
  switch (state.visibility) {
    case 'closed':
      return 'hidden';
    case 'opening':
      return 'showing';
    case 'open':
      return 'visible';
    case 'closing':
      return 'hiding';
    default:
      return 'hidden';
  }
}

import {
  arrow,
  autoUpdate,
  flip,
  FloatingArrow,
  FloatingPortal,
  offset,
  shift,
  useClick,
  useClientPoint,
  useDelayGroup,
  useDelayGroupContext,
  useDismiss,
  useFloating,
  useFocus,
  useHover,
  useInteractions,
  useMergeRefs,
  useRole,
  useTransitionStyles,
} from '@floating-ui/react';
import { cloneElement, forwardRef, useEffect, useId, useMemo, useReducer, useRef } from 'react';

import { cn } from '../../utils';
import { mapPlacement, normalizeTriggers } from '../../utils/misc';

import {
  createInitialTooltipFSMState,
  getTooltipVisualState,
  tooltipFSMReducer,
} from './Tooltip.fsm';
import { useTooltipContext } from './TooltipContext';
import { useTouchInteraction } from './useTouchInteraction';

import type { TooltipProps } from './Tooltip.types';
import type { ReactElement } from 'react';


const TOOLTIP_ARROW_GAP_PX = 6;
const TOOLTIP_ARROW_WIDTH_PX = 12;
const TOOLTIP_ARROW_HEIGHT_PX = 6;
const TOOLTIP_TRANSITION_MS = 150;

/**
 * Map DSAi placement to Floating UI placement
 */

/**
 * Normalize trigger prop to array
 */

/**
 * Tooltip Component
 *
 * A fully accessible tooltip component that provides contextual information
 * on hover, focus, or click. Uses Floating UI for intelligent positioning.
 *
 * ACCESSIBILITY FEATURES (WCAG 2.2 AA):
 * - role="tooltip" on the tooltip content
 * - aria-describedby linking trigger to tooltip
 * - Keyboard accessible (visible on focus)
 * - ESC key to dismiss (for click trigger)
 * - Proper focus management
 *
 * SECURITY FEATURES:
 * - Prop whitelisting (no unrestricted spread)
 * - No dangerouslySetInnerHTML
 * - Explicit event handlers only
 *
 * @exampleclear
 *
 * ```tsx
 * // Basic tooltip
 * <Tooltip content="Helpful information">
 *   <button>Hover me</button>
 * </Tooltip>
 *
 * // Tooltip with custom placement
 * <Tooltip content="Right side tooltip" placement="right">
 *   <span>Target element</span>
 * </Tooltip>
 *
 * // Click-triggered tooltip
 * <Tooltip content="Click to dismiss" trigger="click">
 *   <button>Click me</button>
 * </Tooltip>
 * ```
 */
export const Tooltip = forwardRef<HTMLElement, TooltipProps>(
  (
    {
      children,
      content,
      placement = 'top',
      trigger = ['hover', 'focus'],
      showDelay,
      hideDelay,
      describeChild,
      followCursor,
      touchEnabled,
      arrow: showArrow,
      offset: offsetValue = 8,
      maxWidth,
      isOpen: controlledIsOpen,
      onOpenChange,
      defaultOpen = false,
      disabled = false,
      portal = true,
      container,
      className = '',
      style,
      id,
      'data-testid': dataTestId,
      'data-test': dataTest,
      'aria-label': ariaLabel,
    },
    ref
  ) => {
    // Read provider defaults
    const ctx = useTooltipContext();

    // Resolve props: instance > provider > built-in defaults
    const resolvedShowDelay = showDelay ?? ctx.showDelay;
    const resolvedHideDelay = hideDelay ?? ctx.hideDelay;
    const resolvedArrow = showArrow ?? ctx.arrow;
    const resolvedDescribeChild = describeChild ?? ctx.describeChild;
    const resolvedTouchEnabled = touchEnabled ?? ctx.touchEnabled;

    // Follow-cursor suppresses arrow (moving tooltip + arrow is disorienting)
    const effectiveArrow = followCursor ? false : resolvedArrow;

    if (process.env['NODE_ENV'] !== 'production' && followCursor && showArrow === true) {
      console.warn('Tooltip: arrow is disabled when followCursor is active.');
    }

    // Determine if controlled
    const isControlled = controlledIsOpen !== undefined;

    // Generate unique ID for tooltip
    const generatedId = useId();
    const tooltipId = id ?? `tooltip-${generatedId}`;

    // Arrow ref for Floating UI
    const arrowRef = useRef<SVGSVGElement>(null);

    // FSM for state management
    const [fsmState, dispatch] = useReducer(
      tooltipFSMReducer,
      isControlled ? controlledIsOpen : defaultOpen,
      createInitialTooltipFSMState
    );

    // Compute isOpen from FSM
    const isOpen = fsmState.visibility === 'open' || fsmState.visibility === 'opening';

    // Normalize triggers
    const triggers = useMemo(() => normalizeTriggers(trigger), [trigger]);
    const hasHover = triggers.includes('hover');
    const hasFocus = triggers.includes('focus');
    const hasClick = triggers.includes('click');

    // Build middleware array
    // Note: arrow middleware needs to be included even if showArrow is false
    // to avoid React hooks ordering issues. FloatingArrow handles visibility.
    const middleware = useMemo(
      () => [
        offset(offsetValue + (effectiveArrow ? TOOLTIP_ARROW_GAP_PX : 0)),
        flip({ fallbackAxisSideDirection: 'start' }),
        shift({ padding: 5 }),
        // eslint-disable-next-line react-hooks/refs -- Floating UI documented pattern: arrow middleware requires ref object
        arrow({ element: arrowRef }),
      ],
      [offsetValue, effectiveArrow]
    );

    // Floating UI setup
    const { refs, floatingStyles, context, update } = useFloating({
      open: fsmState.shouldRender,
      onOpenChange: (openState) => {
        if (disabled) {
          return;
        }
        if (openState) {
          dispatch({ type: 'OPEN' });
          onOpenChange?.(true);
        } else {
          dispatch({ type: 'CLOSE' });
          onOpenChange?.(false);
        }
      },
      placement: mapPlacement(placement),
      middleware,
      whileElementsMounted: autoUpdate,
    });

    // Participate in delay groups (if wrapped in TooltipGroup)
    useDelayGroup(context, { id: tooltipId });

    // Read group context for skip-delay behavior.
    // When no FloatingDelayGroup is present the default context returns { delay: 0 }.
    // We must not let that zero override the resolved show/hide delays, so we only
    // use groupDelay when it is truthy (a non-zero number or a delay object).
    const { delay: groupDelay } = useDelayGroupContext();

    // Interaction hooks
    const hover = useHover(context, {
      enabled: hasHover && !disabled,
      delay: groupDelay || {
        open: resolvedShowDelay,
        close: resolvedHideDelay,
      },
      move: false,
    });

    const focus = useFocus(context, {
      enabled: hasFocus && !disabled,
    });

    const click = useClick(context, {
      enabled: hasClick && !disabled,
      toggle: true,
    });

    const dismiss = useDismiss(context, {
      enabled: hasClick,
      escapeKey: true,
    });

    const role = useRole(context, {
      role: resolvedDescribeChild ? 'tooltip' : 'label',
    });

    const clientPoint = useClientPoint(context, {
      enabled: !!followCursor && !disabled,
      axis: followCursor === true ? 'both' : (followCursor || 'both'),
    });

    // Touch interaction (long-press)
    const touchInteraction = useTouchInteraction({
      enabled: resolvedTouchEnabled && !disabled,
      onOpen: () => {
        dispatch({ type: 'OPEN' });
        onOpenChange?.(true);
      },
      onClose: () => {
        dispatch({ type: 'CLOSE' });
        onOpenChange?.(false);
      },
    });

    const { getReferenceProps, getFloatingProps } = useInteractions([
      hover,
      focus,
      click,
      dismiss,
      role,
      clientPoint,
    ]);

    // Transition styles for animation
    const { isMounted, styles: transitionStyles } = useTransitionStyles(context, {
      duration: TOOLTIP_TRANSITION_MS,
      initial: {
        opacity: 0,
      },
      open: {
        opacity: 1,
      },
      close: {
        opacity: 0,
      },
    });

    // Sync controlled state with FSM
    useEffect(() => {
      if (!isControlled) {
        return;
      }

      if (controlledIsOpen && fsmState.visibility === 'closed') {
        dispatch({ type: 'OPEN' });
      } else if (
        !controlledIsOpen &&
        (fsmState.visibility === 'open' || fsmState.visibility === 'opening')
      ) {
        dispatch({ type: 'CLOSE' });
      }
    }, [isControlled, controlledIsOpen, fsmState.visibility]);

    // Handle animation end
    useEffect(() => {
      if (fsmState.visibility === 'opening') {
        const frameId = requestAnimationFrame(() => {
          dispatch({ type: 'ANIMATION_END' });
        });
        return () => cancelAnimationFrame(frameId);
      }

      if (fsmState.visibility === 'closing') {
        const timeoutId = setTimeout(() => {
          dispatch({ type: 'ANIMATION_END' });
        }, TOOLTIP_TRANSITION_MS); // Match transition duration
        return () => clearTimeout(timeoutId);
      }

      return undefined;
    }, [fsmState.visibility]);

    // Force a Floating UI re-measure right after paint whenever the tooltip should render.
    // Using requestAnimationFrame ensures the reference element has a layout box before measuring,
    // preventing the tooltip from briefly appearing at (0, 0).
    useEffect(() => {
      if (!fsmState.shouldRender) {
        return undefined;
      }

      const frameId = requestAnimationFrame(() => {
        update();
      });

      return () => cancelAnimationFrame(frameId);
    }, [fsmState.shouldRender, update]);

    const child = children as ReactElement<{ ref?: React.Ref<HTMLElement> }>;
    const childRef = child?.props?.ref;

    const mergedRef = useMergeRefs([ref, refs.setReference, childRef]);

    const triggerElement = useMemo(() => {
      if (!children) {
        return null;
      }

      const ariaProps: Record<string, string | undefined> = resolvedDescribeChild
        ? { 'aria-describedby': isOpen ? tooltipId : undefined }
        : { 'aria-labelledby': isOpen ? tooltipId : undefined };

      return cloneElement(
        child,
        getReferenceProps({
          ref: mergedRef,
          ...ariaProps,
          ...(resolvedTouchEnabled ? touchInteraction : {}),
        })
      );
    }, [
      children, child, getReferenceProps, mergedRef, isOpen, tooltipId,
      resolvedDescribeChild, resolvedTouchEnabled, touchInteraction,
    ]);

    // Compute tooltip styles
    const tooltipStyles = useMemo(() => {
      const { transform: floatingTransform, ...floatingRest } = floatingStyles;
      const { transform: transitionTransform, ...transitionRest } = transitionStyles;

      const combinedTransform = cn(floatingTransform, transitionTransform);

      const baseStyles: React.CSSProperties = {
        ...floatingRest,
        ...transitionRest,
        ...style,
        zIndex: 1080, // Bootstrap tooltip z-index
      };

      if (combinedTransform) {
        baseStyles.transform = combinedTransform;
      }

      if (maxWidth !== undefined) {
        baseStyles.maxWidth = typeof maxWidth === 'number' ? `${maxWidth}px` : maxWidth;
      }

      return baseStyles;
    }, [floatingStyles, transitionStyles, style, maxWidth]);

    // Compute tooltip class names
    const tooltipClassName = useMemo(() => {
      return cn('tooltip', 'bs-tooltip-auto', 'show', className);
    }, [className]);

    // Tooltip content
    const tooltipContent = isMounted ? (
      <div
        ref={refs.setFloating}
        {...getFloatingProps()}
        id={tooltipId}
        role="tooltip"
        className={tooltipClassName}
        style={tooltipStyles}
        aria-label={ariaLabel}
        data-visual-state={getTooltipVisualState(fsmState)}
        data-testid={dataTestId}
        data-test={dataTest}
      >
        {effectiveArrow && (
          <FloatingArrow
            ref={arrowRef}
            context={context}
            className="dsai-tooltip-arrow"
            width={TOOLTIP_ARROW_WIDTH_PX}
            height={TOOLTIP_ARROW_HEIGHT_PX}
            tipRadius={0}
            style={{
              fill: 'var(--bs-tooltip-bg, #212529)',
              pointerEvents: 'none',
            }}
          />
        )}
        <div className="tooltip-inner">{content}</div>
      </div>
    ) : null;

    return (
      <>
        {triggerElement}
        {portal ? (
          <FloatingPortal root={container}>{tooltipContent}</FloatingPortal>
        ) : (
          tooltipContent
        )}
      </>
    );
  }
);

Tooltip.displayName = 'Tooltip';

export type {
  TooltipContextValue,
  TooltipFSMEvent,
  TooltipFSMState,
  TooltipPlacement,
  TooltipProps,
  TooltipTrigger,
  TooltipVisualState,
} from './Tooltip.types';

import type { SafeHTMLAttributes } from '../../types';
import type { ReactElement, ReactNode } from 'react';

/**
 * Tooltip placement options
 * Maps to Floating UI placement values
 */
export type TooltipPlacement =
  | 'top'
  | 'top-start'
  | 'top-end'
  | 'bottom'
  | 'bottom-start'
  | 'bottom-end'
  | 'left'
  | 'left-start'
  | 'left-end'
  | 'right'
  | 'right-start'
  | 'right-end';

/**
 * Tooltip trigger types
 */
export type TooltipTrigger = 'hover' | 'focus' | 'click';

/**
 * Safe HTML attributes that can be spread onto tooltip elements
 * SECURITY: This whitelist prevents injection of dangerous attributes or event handlers
 * @see {@link SafeHTMLAttributes}
 */
export type SafeTooltipHTMLAttributes = SafeHTMLAttributes<HTMLDivElement>;

/**
 * Tooltip component props
 *
 * A fully accessible tooltip component that provides contextual information
 * on hover, focus, or click. Uses Floating UI for intelligent positioning.
 *
 * ACCESSIBILITY FEATURES (WCAG 2.2 AA):
 * - role="tooltip" on the tooltip content
 * - aria-describedby linking trigger to tooltip
 * - Keyboard accessible (visible on focus)
 * - ESC key to dismiss (for click trigger)
 * - Proper focus management
 *
 * SECURITY FEATURES:
 * - Prop whitelisting (no unrestricted spread)
 * - No dangerouslySetInnerHTML
 * - Explicit event handlers only
 *
 * @example
 * ```tsx
 * // Basic tooltip
 * <Tooltip content="Helpful information">
 *   <button>Hover me</button>
 * </Tooltip>
 *
 * // Tooltip with custom placement
 * <Tooltip content="Right side tooltip" placement="right">
 *   <span>Target element</span>
 * </Tooltip>
 *
 * // Click-triggered tooltip
 * <Tooltip content="Click to dismiss" trigger="click">
 *   <button>Click me</button>
 * </Tooltip>
 *
 * // Tooltip with delay
 * <Tooltip content="Delayed tooltip" showDelay={500} hideDelay={200}>
 *   <button>Hover with delay</button>
 * </Tooltip>
 * ```
 */
export interface TooltipProps extends SafeTooltipHTMLAttributes {
  /**
   * The element that triggers the tooltip.
   * Must be a single React element that accepts ref forwarding.
   */
  children: ReactElement;

  /**
   * Tooltip content to display.
   * Can be text or any React node.
   */
  content: ReactNode;

  /**
   * Placement of the tooltip relative to the trigger element.
   * Uses Floating UI for positioning with auto-flip on viewport edges.
   * @default 'top'
   */
  placement?: TooltipPlacement;

  /**
   * How to trigger the tooltip visibility.
   * - 'hover': Show on mouse hover (default)
   * - 'focus': Show on keyboard focus
   * - 'click': Show/hide on click
   *
   * Note: Multiple triggers can be combined using an array.
   * @default ['hover', 'focus']
   */
  trigger?: TooltipTrigger | TooltipTrigger[];

  /**
   * Delay in milliseconds before showing the tooltip.
   * @default 300
   */
  showDelay?: number;

  /**
   * Delay in milliseconds before hiding the tooltip.
   * @default 150
   */
  hideDelay?: number;

  /**
   * Whether to show the arrow pointer.
   * @default true
   */
  arrow?: boolean;

  /**
   * Offset from the trigger element in pixels.
   * @default 8
   */
  offset?: number;

  /**
   * Maximum width of the tooltip content.
   * Use for long text that should wrap.
   * @default undefined (no max-width)
   */
  maxWidth?: number | string;

  /**
   * Controlled open state.
   * If provided, tooltip becomes controlled.
   */
  isOpen?: boolean;

  /**
   * Callback when open state changes.
   * Called when tooltip opens or closes.
   */
  onOpenChange?: (isOpen: boolean) => void;

  /**
   * Default open state for uncontrolled mode.
   * @default false
   */
  defaultOpen?: boolean;

  /**
   * Whether the tooltip is disabled.
   * When disabled, the tooltip will not show.
   * @default false
   */
  disabled?: boolean;

  /**
   * Whether to render the tooltip in a portal.
   * @default true
   */
  portal?: boolean;

  /**
   * Container element for the portal.
   * @default document.body
   */
  container?: HTMLElement | null;

  /**
   * ARIA label for accessibility.
   * Used when content is complex (not a simple string).
   */
  'aria-label'?: string;

  /**
   * When true, tooltip acts as accessible description (aria-describedby).
   * When false, tooltip acts as accessible label (aria-labelledby).
   * Use false for icon-only buttons where the tooltip IS the label.
   * @default true
   */
  describeChild?: boolean;

  /**
   * Track cursor movement.
   * - true: both axes
   * - 'x': horizontal only (timelines, sliders)
   * - 'y': vertical only (data tables)
   * - false: anchored to trigger (default)
   *
   * Arrow is auto-disabled when followCursor is active.
   * @default false
   */
  followCursor?: boolean | 'x' | 'y';

  /**
   * Enable tooltip on touch devices via long-press (700ms).
   * Auto-hides after 1500ms. When false, touch interactions are suppressed.
   * @default false
   */
  touchEnabled?: boolean;
}

/**
 * Props for TooltipProvider — sets global defaults for all descendant Tooltips.
 *
 * Resolution order: instance prop > TooltipProvider > built-in defaults.
 */
export interface TooltipProviderProps {
  children: ReactNode;
  /** Default show delay in ms. @default 300 */
  showDelay?: number;
  /** Default hide delay in ms. @default 150 */
  hideDelay?: number;
  /** Default skip delay for tooltip groups in ms. @default 300 */
  skipDelay?: number;
  /** Default arrow visibility. @default true */
  arrow?: boolean;
  /** Default touch behavior. @default false */
  touchEnabled?: boolean;
  /** Default describeChild behavior. @default true */
  describeChild?: boolean;
}

/**
 * Props for TooltipGroup — coordinates delay timing across sibling tooltips.
 * When one tooltip closes, others in the group open instantly during the skip window.
 */
export interface TooltipGroupProps {
  children: ReactNode;
  /** Time window (ms) after close during which next tooltip opens instantly.
   *  @default inherits from TooltipProvider (300ms) */
  skipDelay?: number;
}

/**
 * Tooltip context value for sharing state between components
 */
export interface TooltipContextValue {
  /** Whether the tooltip is currently visible */
  isOpen: boolean;
  /** Open the tooltip */
  open: () => void;
  /** Close the tooltip */
  close: () => void;
  /** Toggle the tooltip */
  toggle: () => void;
  /** Whether the tooltip is disabled */
  disabled: boolean;
  /** Tooltip ID for aria-describedby */
  tooltipId: string;
  /** Current placement of the tooltip */
  placement: TooltipPlacement;
}

/**
 * Internal FSM state for tooltip visibility
 */
export interface TooltipFSMState {
  /** Current visibility state */
  visibility: 'closed' | 'opening' | 'open' | 'closing';
  /** Whether the tooltip should be rendered in DOM */
  shouldRender: boolean;
}

/**
 * FSM events for tooltip state transitions
 */
export type TooltipFSMEvent = { type: 'OPEN' } | { type: 'CLOSE' } | { type: 'ANIMATION_END' };

/**
 * Visual state for data attribute (for CSS styling and testing)
 */
export type TooltipVisualState = 'hidden' | 'showing' | 'visible' | 'hiding';

import { createContext, useContext } from 'react';

export interface TooltipProviderContextValue {
  showDelay: number;
  hideDelay: number;
  skipDelay: number;
  arrow: boolean;
  touchEnabled: boolean;
  describeChild: boolean;
}

export const TOOLTIP_DEFAULTS: TooltipProviderContextValue = {
  showDelay: 300,
  hideDelay: 150,
  skipDelay: 300,
  arrow: true,
  touchEnabled: false,
  describeChild: true,
};

export const TooltipProviderContext =
  createContext<TooltipProviderContextValue>(TOOLTIP_DEFAULTS);

/**
 * Read current tooltip defaults from the nearest TooltipProvider.
 * Falls back to TOOLTIP_DEFAULTS when no provider is present.
 */
export function useTooltipContext(): TooltipProviderContextValue {
  return useContext(TooltipProviderContext);
}

import { FloatingDelayGroup } from '@floating-ui/react';

import { useTooltipContext } from './TooltipContext';

import type { TooltipGroupProps } from './Tooltip.types';

/**
 * TooltipGroup — coordinates delay timing across sibling tooltips.
 *
 * When one tooltip is open and the user moves to another within the skip window,
 * the second tooltip opens instantly (no show delay).
 *
 * @example
 * ```tsx
 * <TooltipGroup>
 *   <Tooltip content="Bold"><Button>B</Button></Tooltip>
 *   <Tooltip content="Italic"><Button>I</Button></Tooltip>
 *   <Tooltip content="Underline"><Button>U</Button></Tooltip>
 * </TooltipGroup>
 * ```
 */
export function TooltipGroup({
  children,
  skipDelay,
}: TooltipGroupProps): React.JSX.Element {
  const ctx = useTooltipContext();
  const resolvedSkipDelay = skipDelay ?? ctx.skipDelay;

  return (
    <FloatingDelayGroup
      delay={{ open: ctx.showDelay, close: ctx.hideDelay }}
      timeoutMs={resolvedSkipDelay}
    >
      {children}
    </FloatingDelayGroup>
  );
}

TooltipGroup.displayName = 'TooltipGroup';

import {
  TooltipProviderContext,
  useTooltipContext,
} from './TooltipContext';

import type { TooltipProviderProps } from './Tooltip.types';

/**
 * TooltipProvider — sets global defaults for all descendant Tooltips.
 *
 * Resolution order: instance prop > TooltipProvider context > built-in defaults.
 *
 * @example
 * ```tsx
 * <TooltipProvider showDelay={400} touchEnabled={false}>
 *   <App />
 * </TooltipProvider>
 * ```
 */
export function TooltipProvider({
  children,
  showDelay,
  hideDelay,
  skipDelay,
  arrow,
  touchEnabled,
  describeChild,
}: TooltipProviderProps): React.JSX.Element {
  const parent = useTooltipContext();

  const value = {
    showDelay: showDelay ?? parent.showDelay,
    hideDelay: hideDelay ?? parent.hideDelay,
    skipDelay: skipDelay ?? parent.skipDelay,
    arrow: arrow ?? parent.arrow,
    touchEnabled: touchEnabled ?? parent.touchEnabled,
    describeChild: describeChild ?? parent.describeChild,
  };

  return (
    <TooltipProviderContext.Provider value={value}>
      {children}
    </TooltipProviderContext.Provider>
  );
}

TooltipProvider.displayName = 'TooltipProvider';

import { useCallback, useRef } from 'react';

const LONG_PRESS_MS = 700;
const AUTO_HIDE_MS = 1500;
const MOVE_THRESHOLD_PX = 10;

interface UseTouchInteractionOptions {
  enabled: boolean;
  onOpen: () => void;
  onClose: () => void;
}

interface TouchInteractionProps {
  onTouchStart: (e: React.TouchEvent) => void;
  onTouchMove: (e: React.TouchEvent) => void;
  onTouchEnd: () => void;
}

/**
 * Internal hook for long-press touch interaction on tooltips.
 *
 * - Long-press (700ms) to show
 * - Auto-hide after 1500ms
 * - Cancel on scroll (>10px movement) or touch end before threshold
 */
export function useTouchInteraction({
  enabled,
  onOpen,
  onClose,
}: UseTouchInteractionOptions): TouchInteractionProps {
  const longPressTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const autoHideTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const startPosRef = useRef<{ x: number; y: number } | null>(null);

  const clearTimers = useCallback(() => {
    if (longPressTimerRef.current !== null) {
      clearTimeout(longPressTimerRef.current);
      longPressTimerRef.current = null;
    }
    if (autoHideTimerRef.current !== null) {
      clearTimeout(autoHideTimerRef.current);
      autoHideTimerRef.current = null;
    }
  }, []);

  const onTouchStart = useCallback(
    (e: React.TouchEvent) => {
      if (!enabled) {return;}

      const touch = e.touches[0];
      if (!touch) {return;}

      startPosRef.current = { x: touch.clientX, y: touch.clientY };
      clearTimers();

      longPressTimerRef.current = setTimeout(() => {
        longPressTimerRef.current = null;
        onOpen();

        autoHideTimerRef.current = setTimeout(() => {
          autoHideTimerRef.current = null;
          onClose();
        }, AUTO_HIDE_MS);
      }, LONG_PRESS_MS);
    },
    [enabled, onOpen, onClose, clearTimers],
  );

  const onTouchMove = useCallback(
    (e: React.TouchEvent) => {
      if (!startPosRef.current) {return;}

      const touch = e.touches[0];
      if (!touch) {return;}

      const dx = touch.clientX - startPosRef.current.x;
      const dy = touch.clientY - startPosRef.current.y;
      const distance = Math.sqrt(dx * dx + dy * dy);

      if (distance > MOVE_THRESHOLD_PX) {
        clearTimers();
        startPosRef.current = null;
      }
    },
    [clearTimers],
  );

  const onTouchEnd = useCallback(() => {
    // If long-press timer is still active, user released early — cancel
    if (longPressTimerRef.current !== null) {
      clearTimers();
    }
    startPosRef.current = null;
  }, [clearTimers]);

  return { onTouchStart, onTouchMove, onTouchEnd };
}
